{
  "case_id": "xsu_sg_002_permanence_requirement",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret gengiver korrekt udgangspunktet om varighed og étårsreglen, men udelader, at tidsbegrænset tillæg kan gives, når varighed er sandsynliggjort men ikke endeligt fastslået. Det er en del af spørgsmålet om, hvad der gælder, hvis tilstanden ikke er varig fra begyndelsen. Svaret fremstår derfor ikke fuldt dækkende. Det angiver heller ikke, at varigheden vedrører funktionsnedsættelsens art og grad."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "To af de fire kritiske elementer mangler: (1) at varigheden vedrører funktionsnedsættelsens art og grad, og (4) at tidsbegrænset tillæg kan gives, når varighed er sandsynliggjort men ikke endeligt fastslået. Element 2 og 3 er dækket."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret behandler begge dele af spørgsmålet: hvornår en funktionsnedsættelse er varig, og hvad der gælder, hvis den ikke er varig fra begyndelsen. Teksten er til sagen. Det, der mangler, er indhold, ikke relevans."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde, hverken lov, bekendtgørelse eller vejledning. Der er kun almindelig tekst uden henvisninger."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det kan ikke vurderes, om en kilde understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Alle juridiske udsagn i svaret har dækning i vejledningens afsnit 3.4.1.1. Svaret tilføjer ingen regel, betingelse eller myndighed uden støtte."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "\"Som udgangspunkt\", \"omkring et år\" og \"normalt\" er bevaret. Svaret mangler dog den påkrævede kvalifikation om tidsbegrænset tillæg ved sandsynliggjort varighed. Det forklarer heller ikke tydeligt, at tidsforløbet alene ikke afgør varigheden; det siger blot, at tilstanden \"kan vurderes\" som varig."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "De få trin hænger sammen: definitionen af varig, derefter udgangspunktet om ikke-varig fra debut, derefter étårsvurderingen. Konklusionen følger af disse trin, og der er ingen modsigelser."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "\"Som udgangspunkt\", \"kan dog vurderes\" og \"normalt\" gengiver vejledningens forbehold. Svaret gør ikke étårsreglen til en absolut regel."
    }
  },
  "xhaile_coverage": {
    "A9": {
      "label": "partial",
      "reason": "Svaret behandler varig funktionsnedsættelse og definerer den som udgangspunkt, men siger ikke eksplicit, at varighed er en grundlæggende forudsætning for tillægget, og nævner ikke art og grad."
    },
    "A12": {
      "label": "yes",
      "reason": "Svaret dækker punktet: som udgangspunkt ikke berettiget, hvis tilstanden ikke var varig eller kronisk fra debut; kan vurderes som varig ved omkring et år; som udgangspunkt symptomer eller følger i mindst et år før ansøgningstidspunktet."
    }
  },
  "overall_notes": "Svaret er korrekt og præcist på det, det siger, med bevarede forbehold, men det er ufuldstændigt. Det mangler muligheden for et tidsbegrænset tillæg ved sandsynliggjort varighed og koblingen til art og grad. Det angiver desuden ingen kilder, så C04 er not_met, og C05 og C06 er not_assessable."
}

